    FILE *fp = fopen("b_seek.bin", "wb");
    int p, q, r, s;
    long pos;
    if (fp == NULL) return 1;
    fprintf(fp, "%d%s", 47, "QRSTUVWX");
    fclose(fp);
    fp = fopen("b_seek.bin", "rb");
    if (fp == NULL) return 1;
    fseek(fp, 2L, SEEK_SET); p = fgetc(fp);
    fseek(fp, 2L, SEEK_CUR); q = fgetc(fp);
    fseek(fp, -1L, SEEK_END); r = fgetc(fp);
    pos = ftell(fp);
    rewind(fp); s = fgetc(fp);
    fclose(fp); remove("b_seek.bin");
    printf("%c%c%c %ld %c", p, q, r, pos, s);
    return 0;
}

